    "questionAr": "مثلث متساوي الساقين مرسوم داخل دائرة نصف قطرها $R = 6\\text{ سم}$ بحيث يقع أحد رؤوسه عند طرف القطر الرأسي. ما هو ارتفاع المثلث $h$ الذي يجعل مساحته أكبر ما يمكن؟",
