    "id": "calc_ch3_db_hots_116",
    "titleEn": "Cone Circumscribed Around Sphere Minimal Volume Ratio",
    "titleAr": "نسبة حجم أصغر مخروط محيط بكرة إلى حجم الكرة",
    "difficulty": "hots",
    "questionEn": "A right circular cone of minimum volume is circumscribed about a sphere of radius $R$. Find the ratio of the volume of this minimal cone to the volume of the sphere.",
    "questionAr": "مخروط دائري قائم أصغر ما يمكن حجماً محيط بكرة نصف قطرها $R$. أوجد النسبة بين حجم هذا المخروط الأصغر إلى حجم الكرة.",
