      "٢. دالة حجم المخروط: ح(ع) = (1/3) ط R² ع² / (ع - 2R).",
      "٣. بالاشتقاق نجد أن الارتفاع الأمثل ع = 4 R.",
      "٤. عند هذا الارتفاع: نق² = 2 R².",
      "٥. حجم المخروط = (8/3) ط R³ = 2 × حجم الكرة.",
      "٦. النسبة بين الحجمين = 2."
