      "٣. دالة حجم الأسطوانة: ح = ط H (نق² - نق³/R).",
      "٤. بالاشتقاق نجد أن نق = (2/3) R و ع = (1/3) H.",
      "٥. حجم الأسطوانة = (4/27) ط R² H = (4/9) V."
