      "2. $g(0) = 1, g(\\pi/2) = 0 \\implies g(b) - g(a) = -1$.",
      "3. Ratio of differences: $\\frac{1}{-1} = -1$.",
      "4. Derivatives: $f'(x) = \\cos x$ and $g'(x) = -\\sin x$, so $\\frac{f'(c)}{g'(c)} = \\frac{\\cos c}{-\\sin c} = -\\cot c$.",
