    "difficulty": "hots",
    "questionEn": "A wire of length $L$ is cut into two pieces. One piece is bent into a square and the other into a circle. To minimize the combined total area, the ratio of the side of the square $s$ to the radius of the circle $r$ must be:",
    "questionAr": "سلك طوله $L$ قُطع إلى قطعتين؛ ثُنيت الأولى لصنع مربع والثانية لصنع دائرة. لكي يكون مجموع مساحتيهما أصغر ما يمكن، ما النسبة بين طول ضلع المربع $s$ إلى نصف قطر الدائرة $r$؟",
